import { canTransitionLeave, countWorkingDays, validateLeaveRequest, addDays, type LeaveContext, type LeaveInput } from '../../src/services/leaveRules';

const TODAY = '2026-03-02'; // Monday
const ctx: LeaveContext = { workingDays: [1, 2, 3, 4, 5, 6], holidays: new Set(), balanceRemaining: 12, overlaps: false };
const req = (over: Partial<LeaveInput> = {}): LeaveInput => ({
  startDate: '2026-03-09',
  endDate: '2026-03-09',
  halfDay: 'NONE',
  reason: 'Family function out of town',
  today: TODAY,
  ...over,
});
const run = (over: Partial<LeaveInput> = {}, c: Partial<LeaveContext> = {}) => validateLeaveRequest(req(over), { ...ctx, ...c });
const fields = (r: ReturnType<typeof run>) => r.issues.map((i) => i.field);

describe('working-day counting', () => {
  it('skips Sundays and holidays', () => {
    expect(countWorkingDays('2026-03-02', '2026-03-08', [1, 2, 3, 4, 5, 6], new Set())).toBe(6);
    expect(countWorkingDays('2026-03-02', '2026-03-08', [1, 2, 3, 4, 5, 6], new Set(['2026-03-04']))).toBe(5);
    expect(countWorkingDays('2026-03-02', '2026-03-08', [1, 2, 3, 4, 5], new Set())).toBe(5);
  });
  it('adds days across month ends', () => {
    expect(addDays('2026-02-28', 1)).toBe('2026-03-01');
    expect(addDays('2026-03-01', -1)).toBe('2026-02-28');
  });
});

describe('length boundaries (REQ-LEAVE-02)', () => {
  it('accepts 1 working day', () => expect(run()).toEqual({ days: 1, issues: [] }));
  it('accepts exactly 15 working days', () => {
    // Mon 9 Mar to Tue 31 Mar with Sundays off = 15 days on 9..24 March (9-14, 16-21, 23-25)
    const r = run({ startDate: '2026-03-09', endDate: '2026-03-25' }, { balanceRemaining: 20 });
    expect(r.days).toBe(15);
    expect(r.issues).toEqual([]);
  });
  it('rejects 16 working days', () => {
    const r = run({ startDate: '2026-03-09', endDate: '2026-03-26' }, { balanceRemaining: 20 });
    expect(r.days).toBe(16);
    expect(fields(r)).toEqual(['endDate']);
  });
  it('rejects a range with no working days', () => {
    expect(fields(run({ startDate: '2026-03-08', endDate: '2026-03-08' }))).toEqual(['startDate']);
    expect(fields(run({}, { holidays: new Set(['2026-03-09']) }))).toEqual(['startDate']);
  });
});

describe('date window and format', () => {
  it('allows a start 30 days back but not 31', () => {
    expect(run({ startDate: '2026-01-31', endDate: '2026-01-31' }).issues).toEqual([]);
    expect(fields(run({ startDate: '2026-01-30', endDate: '2026-01-30' }))).toEqual(['startDate']);
  });
  it('allows a start 365 days ahead but not 366', () => {
    expect(run({ startDate: '2027-03-02', endDate: '2027-03-02' }).issues).toEqual([]);
    expect(fields(run({ startDate: '2027-03-03', endDate: '2027-03-03' }))).toEqual(['startDate']);
  });
  it('rejects end before start, bad dates and cross-year ranges', () => {
    expect(fields(run({ startDate: '2026-03-10', endDate: '2026-03-09' }))).toEqual(['endDate']);
    expect(fields(run({ startDate: '2026-02-30' }))).toEqual(['startDate']);
    expect(fields(run({ endDate: 'soon' }))).toEqual(['endDate']);
    expect(fields(run({ startDate: '2026-12-30', endDate: '2027-01-02' }, { balanceRemaining: 20 }))).toContain('endDate');
  });
});

describe('reason length', () => {
  it.each([
    ['too short', 'x'.repeat(9), false],
    ['minimum', 'x'.repeat(10), true],
    ['maximum', 'x'.repeat(300), true],
    ['too long', 'x'.repeat(301), false],
    ['padding is trimmed', `   ${'x'.repeat(9)}   `, false],
  ])('%s', (_n, reason, valid) => {
    expect(run({ reason }).issues.length === 0).toBe(valid);
  });
});

describe('half day (REQ-LEAVE-03)', () => {
  it('counts 0.5 for a single day', () => {
    expect(run({ halfDay: 'FIRST_HALF' }).days).toBe(0.5);
    expect(run({ halfDay: 'SECOND_HALF' }).days).toBe(0.5);
  });
  it('rejects a multi-day half-day leave and a non-working day', () => {
    expect(fields(run({ halfDay: 'FIRST_HALF', endDate: '2026-03-10' }))).toEqual(['halfDay']);
    expect(fields(run({ halfDay: 'FIRST_HALF', startDate: '2026-03-08', endDate: '2026-03-08' }))).toEqual(['startDate']);
  });
});

describe('overlap and balance', () => {
  it('flags an overlap', () => {
    expect(run({}, { overlaps: true }).issues).toMatchObject([{ code: 'OVERLAP' }]);
  });
  it('allows exactly the remaining balance and rejects one more', () => {
    expect(run({}, { balanceRemaining: 1 }).issues).toEqual([]);
    expect(run({}, { balanceRemaining: 0.5 }).issues).toMatchObject([{ code: 'INSUFFICIENT_BALANCE' }]);
    expect(run({ halfDay: 'FIRST_HALF' }, { balanceRemaining: 0.5 }).issues).toEqual([]);
  });
  it('unlimited leave types ignore balance', () => {
    expect(run({}, { balanceRemaining: null }).issues).toEqual([]);
  });
});

describe('state machine (REQ-LEAVE-04)', () => {
  const future = { startDate: '2026-03-09', today: TODAY };
  const ok: Array<[string, string]> = [
    ['DRAFT', 'PENDING'],
    ['PENDING', 'APPROVED'],
    ['PENDING', 'REJECTED'],
    ['PENDING', 'CANCELLED'],
    ['APPROVED', 'CANCELLED'],
  ];
  it.each(ok)('%s -> %s is allowed', (from, to) => {
    expect(canTransitionLeave(from as never, to as never, future)).toEqual({ allowed: true });
  });

  const all = ['DRAFT', 'PENDING', 'APPROVED', 'REJECTED', 'CANCELLED'];
  const bad = all.flatMap((f) => all.map((t) => [f, t] as [string, string])).filter(([f, t]) => !ok.some(([a, b]) => a === f && b === t));
  it.each(bad)('%s -> %s is refused', (from, to) => {
    expect(canTransitionLeave(from as never, to as never, future).allowed).toBe(false);
  });

  it('approved leave can be cancelled only before its start date', () => {
    expect(canTransitionLeave('APPROVED', 'CANCELLED', { startDate: '2026-03-03', today: TODAY }).allowed).toBe(true);
    expect(canTransitionLeave('APPROVED', 'CANCELLED', { startDate: TODAY, today: TODAY }).allowed).toBe(false);
    expect(canTransitionLeave('APPROVED', 'CANCELLED', { startDate: '2026-03-01', today: TODAY }).allowed).toBe(false);
  });
});

tests/unit/computeDailyStatus.test.ts.source:
import {
  classifyArrival,
  classifyHours,
  computeDailyStatus,
  workedMinutesBetween,
  type DailyStatusInput,
} from '../../src/services/attendanceRules';
import { DEFAULT_RULES, MONDAY, ist } from '../helpers/time';

const base = { shiftStart: '09:00', rules: DEFAULT_RULES };
const day = (over: Partial<DailyStatusInput>): DailyStatusInput => ({ dayType: 'WORKING', ...base, ...over });

describe('arrival boundaries (REQ-RULE-02)', () => {
  it.each([
    ['08:59', 'ON_TIME'],
    ['09:00', 'ON_TIME'],
    ['09:15', 'ON_TIME'],
    ['09:15:59', 'ON_TIME'],
    ['09:16', 'LATE'],
    ['10:30', 'LATE'],
    ['10:30:59', 'LATE'],
    ['10:31', 'HALF_DAY'],
    ['11:59', 'HALF_DAY'],
  ])('check-in at %s is %s', (time, expected) => {
    expect(classifyArrival(ist(MONDAY, time), '09:00', DEFAULT_RULES)).toBe(expected);
  });

  it('follows a changed grace period', () => {
    const rules = { ...DEFAULT_RULES, graceMinutes: 0 };
    expect(classifyArrival(ist(MONDAY, '09:00'), '09:00', rules)).toBe('ON_TIME');
    expect(classifyArrival(ist(MONDAY, '09:01'), '09:00', rules)).toBe('LATE');
    const wide = { ...DEFAULT_RULES, graceMinutes: 60 };
    expect(classifyArrival(ist(MONDAY, '10:00'), '09:00', wide)).toBe('ON_TIME');
    expect(classifyArrival(ist(MONDAY, '10:01'), '09:00', wide)).toBe('LATE');
  });

  it('uses the shift start, not a fixed 09:00', () => {
    expect(classifyArrival(ist(MONDAY, '08:30'), '08:00', DEFAULT_RULES)).toBe('LATE');
  });
});

describe('worked-hours boundaries (REQ-RULE-03)', () => {
  it.each([
    [0, 'ABSENT'],
    [239, 'ABSENT'],
    [240, 'HALF_DAY'],
    [241, 'HALF_DAY'],
    [419, 'HALF_DAY'],
    [420, 'PRESENT'],
    [421, 'PRESENT'],
    [600, 'PRESENT'],
  ])('%i minutes worked is %s', (minutes, expected) => {
    expect(classifyHours(minutes, DEFAULT_RULES)).toBe(expected);
  });

  it('measures whole minutes and never goes negative', () => {
    expect(workedMinutesBetween(ist(MONDAY, '09:00'), ist(MONDAY, '09:00:59'))).toBe(0);
    expect(workedMinutesBetween(ist(MONDAY, '09:00'), ist(MONDAY, '16:00'))).toBe(420);
    expect(workedMinutesBetween(ist(MONDAY, '10:00'), ist(MONDAY, '09:00'))).toBe(0);
  });
});

describe('combined daily status', () => {
  const run = (inT: string, outT: string | null, over: Partial<DailyStatusInput> = {}) =>
    computeDailyStatus(day({ checkInAt: ist(MONDAY, inT), checkOutAt: outT ? ist(MONDAY, outT) : null, ...over }));

  it('on time and a full day is Present', () => {
    expect(run('09:00', '17:00')).toMatchObject({ status: 'PRESENT', workedMinutes: 480, arrival: 'ON_TIME' });
  });
  it('exactly 7 hours is Present and 6h59 is Half Day (6:59 / 7:00 boundary)', () => {
    expect(run('09:00', '16:00').status).toBe('PRESENT');
    expect(run('09:00', '15:59').status).toBe('HALF_DAY');
  });
  it('exactly 4 hours is Half Day and 3h59 is Absent (3:59 / 4:00 boundary)', () => {
    expect(run('09:00', '13:00').status).toBe('HALF_DAY');
    expect(run('09:00', '12:59').status).toBe('ABSENT');
  });
  it('a late arrival with a full day is Late', () => {
    expect(run('09:16', '17:00').status).toBe('LATE');
    expect(run('10:30', '18:00').status).toBe('LATE');
  });
  it('arriving after 10:30 is Half Day even with 7+ hours', () => {
    expect(run('10:31', '18:00').status).toBe('HALF_DAY');
  });
  it('a late arrival with a short day is Half Day, and under 4 hours is Absent', () => {
    expect(run('09:30', '14:00').status).toBe('HALF_DAY');
    expect(run('09:30', '12:00').status).toBe('ABSENT');
  });
  it('checked in with no check-out is Pending while the day is open', () => {
    expect(run('09:00', null)).toMatchObject({ status: 'PENDING', workedMinutes: null, arrival: 'ON_TIME' });
  });
  it('a missed check-out becomes Half Day once the day is closed', () => {
    expect(run('09:00', null, { dayClosed: true }).status).toBe('HALF_DAY');
  });
  it('no punches on a working day is Absent', () => {
    expect(computeDailyStatus(day({}))).toEqual({ status: 'ABSENT', workedMinutes: null, arrival: null });
  });
});

describe('day types take precedence (REQ-RULE-05)', () => {
  it('a holiday is Holiday', () => {
    expect(computeDailyStatus(day({ dayType: 'HOLIDAY' })).status).toBe('HOLIDAY');
  });
  it('a weekly off is Weekly Off', () => {
    expect(computeDailyStatus(day({ dayType: 'WEEKLY_OFF' })).status).toBe('WEEKLY_OFF');
  });
  it('a holiday beats approved leave, and weekly off beats leave', () => {
    expect(computeDailyStatus(day({ dayType: 'HOLIDAY', leave: 'FULL' })).status).toBe('HOLIDAY');
    expect(computeDailyStatus(day({ dayType: 'WEEKLY_OFF', leave: 'FULL' })).status).toBe('WEEKLY_OFF');
  });
  it('approved full-day leave is On Leave', () => {
    expect(computeDailyStatus(day({ leave: 'FULL' })).status).toBe('ON_LEAVE');
  });
  it('a half-day leave with no punches is Half Day', () => {
    expect(computeDailyStatus(day({ leave: 'HALF' })).status).toBe('HALF_DAY');
  });
  it('a half-day leave with punches is judged on the punches', () => {
    expect(
      computeDailyStatus(day({ leave: 'HALF', checkInAt: ist(MONDAY, '09:00'), checkOutAt: ist(MONDAY, '17:00') })).status,
    ).toBe('PRESENT');
  });
});

