import { parseEmployeeNumber, EMPLOYEE_ID_PATTERN } from '../../src/services/employeeId';
import { canTransitionLeave } from '../../src/services/leaveRules';
import { validateRegularization } from '../../src/services/regularizationRules';

// Added after the first Stryker run to kill surviving mutants (see 05_Test_Automation/Mutation_Testing.md).

describe('employee ID pattern anchors', () => {
  it('rejects a prefix or suffix around a valid ID', () => {
    expect(parseEmployeeNumber('xFAC-0001')).toBeNull();
    expect(parseEmployeeNumber('FAC-0001x')).toBeNull();
    expect(EMPLOYEE_ID_PATTERN.test('FAC-0001\nFAC-0002')).toBe(false);
  });
});

describe('canTransitionLeave details', () => {
  it('blocks cancelling approved leave that starts today, with a message', () => {
    const r = canTransitionLeave('APPROVED', 'CANCELLED', { startDate: '2026-03-10', today: '2026-03-10' });
    expect(r).toEqual({ allowed: false, message: 'Approved leave can be cancelled only before it starts' });
  });
  it('allows cancelling approved leave that starts tomorrow', () => {
    expect(canTransitionLeave('APPROVED', 'CANCELLED', { startDate: '2026-03-11', today: '2026-03-10' })).toEqual({ allowed: true });
  });
  it('does not apply the start-date rule to a pending cancel or an approve', () => {
    expect(canTransitionLeave('PENDING', 'CANCELLED', { startDate: '2026-03-01', today: '2026-03-10' })).toEqual({ allowed: true });
    expect(canTransitionLeave('PENDING', 'APPROVED', { startDate: '2026-03-01', today: '2026-03-10' })).toEqual({ allowed: true });
  });
  it('explains an illegal transition in lower case', () => {
    expect(canTransitionLeave('REJECTED', 'APPROVED', { startDate: '2026-03-10', today: '2026-03-01' })).toEqual({
      allowed: false,
      message: 'A rejected leave request cannot become approved',
    });
  });
});

describe('validateRegularization details', () => {
  const base = { date: '2026-03-09', requestedCheckIn: '09:00', requestedCheckOut: '17:00', reason: 'Biometric was down', today: '2026-03-10' };
  const msgs = (o: Partial<Record<keyof typeof base, string | null>>, n = 0) => validateRegularization({ ...base, ...o } as Parameters<typeof validateRegularization>[0], n).map((i) => `${i.field}:${i.message}`);

  it('accepts a valid request', () => expect(msgs({})).toEqual([]));
  it('reports a malformed date', () => expect(msgs({ date: '2026-13-45' })).toEqual(['date:Date must be a valid YYYY-MM-DD date']));
  it('reports a future date', () => expect(msgs({ date: '2026-03-11' })).toEqual(['date:Date cannot be in the future']));
  it('reports a date outside the window', () => expect(msgs({ date: '2026-03-01' })[0]).toMatch(/^date:Regularization is allowed only for the last 7 days$/));
  it('trims the reason before measuring it', () => expect(msgs({ reason: '   short   ' })[0]).toBe('reason:Reason must be 10-300 characters'));
  it('requires at least one time', () => {
    expect(msgs({ requestedCheckIn: null, requestedCheckOut: null })[0]).toMatch(/^requestedCheckIn:Provide a check-in time/);
  });
  it('rejects malformed times with anchored pattern', () => {
    expect(msgs({ requestedCheckIn: 'x09:00' })).toContain('requestedCheckIn:Check-in time must be HH:mm');
    expect(msgs({ requestedCheckIn: '09:00x' })).toContain('requestedCheckIn:Check-in time must be HH:mm');
    expect(msgs({ requestedCheckOut: '17:00x' })).toContain('requestedCheckOut:Check-out time must be HH:mm');
    expect(msgs({ requestedCheckOut: 'x17:00' })).toContain('requestedCheckOut:Check-out time must be HH:mm');
  });
  it('requires check-out after check-in', () => expect(msgs({ requestedCheckIn: '17:00', requestedCheckOut: '09:00' })).toContain('requestedCheckOut:Check-out must be after check-in'));
  it('enforces the monthly limit with a message', () => {
    expect(validateRegularization(base, 3)).toEqual([
      { field: 'date', code: 'LIMIT_REACHED', message: 'You can raise at most 3 regularization requests per month' },
    ]);
  });
});

tests/unit/csvImport.test.ts.source:
import {
  missingColumns,
  normalizeDesignation,
  parseCsv,
  toRecords,
  validateCsvRows,
} from '../../src/services/csvImport';

const ctx = { departmentCodes: new Set(['CSE', 'ECE']), existingEmails: new Set(['taken@x.test']), today: '2026-03-02' };
const header = 'fullName,email,phone,departmentCode,designation,dateOfJoining';
const run = (...lines: string[]) => validateCsvRows(toRecords(parseCsv([header, ...lines].join('\n'))), ctx);

describe('parseCsv', () => {
  it('handles quotes, escaped quotes, commas and CRLF', () => {
    expect(parseCsv('a,"b,c","d ""q"""\r\n1,2,3\r\n')).toEqual([
      ['a', 'b,c', 'd "q"'],
      ['1', '2', '3'],
    ]);
  });
  it('skips blank lines and handles a missing trailing newline', () => {
    expect(parseCsv('a,b\n\n1,2')).toEqual([['a', 'b'], ['1', '2']]);
  });
});

describe('header handling', () => {
  it('reports missing columns case-insensitively', () => {
    expect(missingColumns(['FULLNAME', 'Email'])).toEqual(['phone', 'departmentCode', 'designation', 'dateOfJoining']);
    expect(missingColumns(header.split(','))).toEqual([]);
  });
});

describe('normalizeDesignation', () => {
  it.each([
    ['Assistant Professor', 'ASSISTANT_PROFESSOR'],
    ['ASSOCIATE_PROFESSOR', 'ASSOCIATE_PROFESSOR'],
    ['  professor ', 'PROFESSOR'],
    ['lecturer', 'LECTURER'],
  ])('%s', (input, out) => expect(normalizeDesignation(input)).toBe(out));
  it('rejects unknown', () => expect(normalizeDesignation('Dean')).toBeUndefined());
});

describe('validateCsvRows (REQ-FAC-04)', () => {
  it('accepts a valid row', () => {
    const r = run('Asha Rao,ASHA@x.test,9876543210,CSE,Assistant Professor,2020-06-01');
    expect(r.errors).toEqual([]);
    expect(r.valid[0]).toEqual({
      row: 2,
      data: { fullName: 'Asha Rao', email: 'asha@x.test', phone: '9876543210', departmentCode: 'CSE', designation: 'ASSISTANT_PROFESSOR', dateOfJoining: '2020-06-01' },
    });
  });

  it('reports row-level errors with the file line number', () => {
    const r = run(
      'Asha Rao,asha@x.test,9876543210,CSE,Lecturer,2020-06-01',
      'B,bad-email,12345,XXX,Dean,2030-01-01',
    );
    expect(r.valid).toHaveLength(1);
    expect(r.errors).toHaveLength(1);
    expect(r.errors[0].row).toBe(3);
    const text = r.errors[0].messages.join(' | ');
    for (const part of ['fullName', 'email', 'phone', 'designation', 'cannot be in the future', 'unknown department']) {
      expect(text).toContain(part);
    }
  });

  it.each([
    ['name with digits', 'Asha 2,a@x.test,9876543210,CSE,Lecturer,2020-06-01', 'fullName'],
    ['phone starting with 5', 'Asha,a@x.test,5876543210,CSE,Lecturer,2020-06-01', 'phone'],
    ['impossible date', 'Asha,a@x.test,9876543210,CSE,Lecturer,2020-02-30', 'valid date'],
    ['existing email', 'Asha,taken@x.test,9876543210,CSE,Lecturer,2020-06-01', 'already registered'],
  ])('rejects %s', (_n, line, expected) => {
    expect(run(line).errors[0].messages.join()).toContain(expected);
  });

  it('flags duplicate emails inside the file', () => {
    const r = run('A B,dup@x.test,9876543210,CSE,Lecturer,2020-06-01', 'C D,dup@x.test,9876543211,ECE,Lecturer,2020-06-01');
    expect(r.valid).toHaveLength(1);
    expect(r.errors[0]).toMatchObject({ row: 3 });
    expect(r.errors[0].messages.join()).toContain('duplicated in this file');
  });

  it('accepts today as the joining date (boundary)', () => {
    expect(run('Asha,a@x.test,9876543210,CSE,Lecturer,2026-03-02').errors).toEqual([]);
    expect(run('Asha,a@x.test,9876543210,CSE,Lecturer,2026-03-03').errors).toHaveLength(1);
  });
});

tests/unit/punchWindow.test.ts.source:
import { checkInWindow, checkOutWindow, isLateDeduction } from '../../src/services/attendanceRules';
import { istMinutes, isoWeekday, istDate, todayIST } from '../../src/utils/dates';
import { msUntilNextRun } from '../../src/jobs/absentJob';
import { DEFAULT_RULES, MONDAY, ist } from '../helpers/time';

describe('check-in window 07:00-12:00 (REQ-ATT-02)', () => {
  it.each([
    ['06:59', false, 'CHECKIN_NOT_OPEN'],
    ['07:00', true, undefined],
    ['09:00', true, undefined],
    ['12:00', true, undefined],
    ['12:00:59', true, undefined],
    ['12:01', false, 'CHECKIN_CLOSED'],
  ])('at %s allowed=%s', (time, allowed, code) => {
    const r = checkInWindow(ist(MONDAY, time), DEFAULT_RULES);
    expect(r.allowed).toBe(allowed);
    if (!r.allowed) expect(r.code).toBe(code);
  });
});

describe('check-out window and ordering (REQ-ATT-02, REQ-ATT-05)', () => {
  const checkIn = ist(MONDAY, '09:00');
  it('requires a check-in first', () => {
    const r = checkOutWindow(ist(MONDAY, '17:00'), null, DEFAULT_RULES);
    expect(r).toMatchObject({ allowed: false, code: 'NOT_CHECKED_IN' });
  });
  it.each([
    ['09:00', false, 'CHECKOUT_BEFORE_CHECKIN'],
    ['09:01', true, undefined],
    ['23:00', true, undefined],
    ['23:01', false, 'CHECKOUT_CLOSED'],
  ])('check-out at %s allowed=%s', (time, allowed, code) => {
    const r = checkOutWindow(ist(MONDAY, time), checkIn, DEFAULT_RULES);
    expect(r.allowed).toBe(allowed);
    if (!r.allowed) expect(r.code).toBe(code);
  });
  it('rejects a check-out before the check-in', () => {
    expect(checkOutWindow(ist(MONDAY, '08:00'), checkIn, DEFAULT_RULES)).toMatchObject({ code: 'CHECKOUT_BEFORE_CHECKIN' });
  });
});

describe('late deduction (REQ-RULE-06)', () => {
  it.each([
    [0, false],
    [1, false],
    [2, true],
    [3, false],
    [4, false],
    [5, true],
  ])('with %i earlier lates this late deduction=%s', (previous, expected) => {
    expect(isLateDeduction(previous, DEFAULT_RULES)).toBe(expected);
  });
  it('is disabled when the limit is 0', () => {
    expect(isLateDeduction(2, { lateLimitPerMonth: 0 })).toBe(false);
  });
});

describe('IST date helpers', () => {
  it('converts UTC instants to the IST calendar day', () => {
    expect(todayIST(new Date('2026-03-01T18:29:59Z'))).toBe('2026-03-01');
    expect(todayIST(new Date('2026-03-01T18:30:00Z'))).toBe('2026-03-02');
    expect(istMinutes(new Date('2026-03-01T18:30:00Z'))).toBe(0);
    expect(istMinutes(ist(MONDAY, '23:59'))).toBe(1439);
    expect(istDate(ist(MONDAY, '00:30')).toISOString()).toBe('2026-03-02T00:00:00.000Z');
  });
  it('maps weekdays with Sunday as 7', () => {
    expect(isoWeekday('2026-03-02')).toBe(1);
    expect(isoWeekday('2026-03-07')).toBe(6);
    expect(isoWeekday('2026-03-08')).toBe(7);
  });
});

describe('nightly schedule', () => {
  it('runs at 23:59 IST the same day, or the next day once past it', () => {
    expect(msUntilNextRun(ist(MONDAY, '23:00'))).toBe(59 * 60_000);
    expect(msUntilNextRun(ist(MONDAY, '23:59'))).toBe(86_400_000);
    expect(msUntilNextRun(ist(MONDAY, '00:00'))).toBe((23 * 60 + 59) * 60_000);
  });
});

tests/unit/regularization.test.ts.source:
import { earliestRegularizableDate, validateRegularization, type RegularizationInput } from '../../src/services/regularizationRules';

const TODAY = '2026-03-10';
const input = (over: Partial<RegularizationInput> = {}): RegularizationInput => ({
  date: '2026-03-09',
  requestedCheckIn: '09:00',
  requestedCheckOut: '17:00',
  reason: 'Forgot to check out yesterday',
  today: TODAY,
  ...over,
});
const fields = (i: Partial<RegularizationInput>, used = 0) => validateRegularization(input(i), used).map((x) => x.field);

describe('date window (REQ-REG-01)', () => {
  it('accepts today and exactly 7 days back', () => {
    expect(fields({ date: TODAY })).toEqual([]);
    expect(fields({ date: '2026-03-03' })).toEqual([]);
    expect(earliestRegularizableDate(TODAY)).toBe('2026-03-03');
  });
  it('rejects 8 days back, the future and invalid dates', () => {
    expect(fields({ date: '2026-03-02' })).toEqual(['date']);
    expect(fields({ date: '2026-03-11' })).toEqual(['date']);
    expect(fields({ date: '2026-02-30' })).toEqual(['date']);
  });
});

describe('reason length (REQ-REG-01)', () => {
  it.each([
    [9, false],
    [10, true],
    [300, true],
    [301, false],
  ])('%i characters valid=%s', (n, valid) => {
    expect(fields({ reason: 'x'.repeat(n) }).length === 0).toBe(valid);
  });
});

describe('times', () => {
  it('needs at least one time, in HH:mm, with check-out after check-in', () => {
    expect(fields({ requestedCheckIn: null, requestedCheckOut: null })).toEqual(['requestedCheckIn']);
    expect(fields({ requestedCheckIn: undefined, requestedCheckOut: '17:00' })).toEqual([]);
    expect(fields({ requestedCheckIn: '9:00' })).toEqual(['requestedCheckIn']);
    expect(fields({ requestedCheckOut: '24:00' })).toEqual(['requestedCheckOut']);
    expect(fields({ requestedCheckIn: '17:00', requestedCheckOut: '17:00' })).toEqual(['requestedCheckOut']);
    expect(fields({ requestedCheckIn: '17:00', requestedCheckOut: '09:00' })).toEqual(['requestedCheckOut']);
  });
});

describe('monthly limit (REQ-REG-02)', () => {
  it('allows the 3rd request and refuses the 4th', () => {
    expect(validateRegularization(input(), 2)).toEqual([]);
    expect(validateRegularization(input(), 3)).toMatchObject([{ code: 'LIMIT_REACHED' }]);
    expect(validateRegularization(input(), 4)).toMatchObject([{ code: 'LIMIT_REACHED' }]);
  });
  it('reports input errors before the limit', () => {
    expect(validateRegularization(input({ reason: 'short' }), 3)).toMatchObject([{ code: 'INVALID' }]);
  });
});

tests/unit/lockout.test.ts.source:
import { LOCK_MINUTES, MAX_FAILED_ATTEMPTS, isLocked, registerFailure } from '../../src/services/lockout';

const NOW = new Date('2026-03-02T10:00:00Z');

describe('lockout (REQ-AUTH-05)', () => {
  it('uses 5 attempts and 15 minutes', () => {
    expect(MAX_FAILED_ATTEMPTS).toBe(5);
    expect(LOCK_MINUTES).toBe(15);
  });

  it.each([
    [0, 1, false],
    [3, 4, false],
    [4, 5, true],
    [5, 6, true],
  ])('previous failures %i -> %i attempts, locked=%s', (prev, attempts, locked) => {
    const r = registerFailure({ failedLoginAttempts: prev, lockedUntil: null }, NOW);
    expect(r.failedLoginAttempts).toBe(attempts);
    expect(r.lockedUntil !== null).toBe(locked);
  });

  it('locks for exactly 15 minutes', () => {
    const r = registerFailure({ failedLoginAttempts: 4, lockedUntil: null }, NOW);
    expect(r.lockedUntil?.getTime()).toBe(NOW.getTime() + 15 * 60_000);
  });

  it('restarts the counter after a lock has expired', () => {
    const expired = new Date(NOW.getTime() - 1);
    const r = registerFailure({ failedLoginAttempts: 5, lockedUntil: expired }, NOW);
    expect(r).toEqual({ failedLoginAttempts: 1, lockedUntil: null });
  });

  it('does not reset the counter while still locked', () => {
    const active = new Date(NOW.getTime() + 60_000);
    expect(registerFailure({ failedLoginAttempts: 5, lockedUntil: active }, NOW).failedLoginAttempts).toBe(6);
  });

  describe('isLocked', () => {
    it('is false when never locked', () => expect(isLocked({ lockedUntil: null }, NOW)).toBe(false));
    it('is true before expiry', () => expect(isLocked({ lockedUntil: new Date(NOW.getTime() + 1) }, NOW)).toBe(true));
    it('is false at the exact expiry instant', () => expect(isLocked({ lockedUntil: NOW }, NOW)).toBe(false));
  });
});

tests/unit/passwordPolicy.test.ts.source:
import { validatePassword } from '../../src/services/passwordPolicy';

const make = (len: number) => 'Aa1!' + 'x'.repeat(Math.max(0, len - 4));

describe('validatePassword (REQ-AUTH-06)', () => {
  describe('length boundaries', () => {
    it.each([
      [7, false],
      [8, true],
      [9, true],
      [63, true],
      [64, true],
      [65, false],
    ])('length %i -> valid=%s', (len, valid) => {
      expect(validatePassword(make(len)).valid).toBe(valid);
    });

    it('reports min and max messages', () => {
      expect(validatePassword('Aa1!xxx').errors).toContain('Password must be at least 8 characters');
      expect(validatePassword(make(65)).errors).toContain('Password must be at most 64 characters');
    });
  });

  describe('character classes', () => {
    it.each([
      ['no uppercase', 'abcdef1!', 'uppercase'],
      ['no lowercase', 'ABCDEF1!', 'lowercase'],
      ['no digit', 'Abcdefg!', 'digit'],
      ['no special', 'Abcdefg1', 'special'],
    ])('%s is rejected', (_name, pw, word) => {
      const r = validatePassword(pw);
      expect(r.valid).toBe(false);
      expect(r.errors).toHaveLength(1);
      expect(r.errors[0]).toContain(word);
    });

    it('accepts a strong password', () => {
      expect(validatePassword('Valid@1234')).toEqual({ valid: true, errors: [] });
    });

    it('collects several errors at once', () => {
      expect(validatePassword('').errors.length).toBe(5);
    });
  });
});

tests/unit/employeeId.test.ts.source:
import { formatEmployeeId, nextEmployeeId, parseEmployeeNumber } from '../../src/services/employeeId';

describe('employee ID generation (REQ-FAC-02)', () => {
  it('starts at FAC-0001', () => expect(nextEmployeeId([])).toBe('FAC-0001'));
  it('increments the highest existing number', () => {
    expect(nextEmployeeId(['FAC-0001', 'FAC-0007', 'FAC-0003'])).toBe('FAC-0008');
  });
  it('pads to 4 digits and grows beyond', () => {
    expect(formatEmployeeId(9)).toBe('FAC-0009');
    expect(formatEmployeeId(9999)).toBe('FAC-9999');
    expect(nextEmployeeId(['FAC-9999'])).toBe('FAC-10000');
  });
  it('ignores malformed IDs', () => {
    expect(nextEmployeeId(['XYZ', 'FAC-12', 'fac-0005', 'FAC-0002'])).toBe('FAC-0003');
  });
  it('parses numbers and rejects bad formats', () => {
    expect(parseEmployeeNumber('FAC-0042')).toBe(42);
    expect(parseEmployeeNumber('FAC-042')).toBeNull();
    expect(parseEmployeeNumber('EMP-0042')).toBeNull();
  });
});
